if (!type) errors.push('Leave type is empty (Jira field {{{_flow.JIRA_ABSENCE_TYPE_FIELD}}})');
else if (!mapTo("{{{_flow.ABSENCE_TYPE_ID_MAP}}}", type)) errors.push('Leave type "' + type + '" has no entry in ABSENCE_TYPE_ID_MAP');
